  "mirror": "export interface MirrorFeature {\n  id: string;\n  type: \"mirror\";\n  name: string;\n  sourceFeatureId: string;\n  plane: SketchPlane;\n  offsetMillimeters: number;\n  /** A plane feature or picked face as the mirror plane; when present it replaces plane + offset. */\n  mirrorPlane?: MirrorPlaneReference;\n  operation: \"add\" | \"cut\";\n  targetBodyId?: string;\n  suppressed: boolean;\n}\n\nexport type MirrorPlaneReference=\n | {kind:'principal';plane:SketchPlane;offsetMillimeters:number}\n | {kind:'feature';featureId:string}\n | ({kind:'face'}&SolidFaceReference)\n /** A straight sketch line: the plane through it along the sketch's normal. */\n | {kind:'sketch-line';sourceFeatureId:string;contourId:string;segmentId:string};\n\nexport type SketchPlane = \"XY\" | \"XZ\" | \"YZ\";\n\nexport type SolidFaceReference=FaceSource & (\n  {normal:[number,number,number];surfaceType?:never} | {surfaceType:CurvedSurfaceType;normal?:never}\n);",
  "offset-face": "export interface OffsetFaceFeature {\n  id:string; type:'offset-face'; name:string; suppressed:boolean;\n  faces:SolidFaceReference[];\n  distanceMillimeters?:number;\n  transform?:FaceTransform;\n  /** Replace Face: the faces move onto this plane (parallel planar faces), the distance computed at build. */\n  replaceWith?:MirrorPlaneReference;\n}\n\nexport type MirrorPlaneReference=\n | {kind:'principal';plane:SketchPlane;offsetMillimeters:number}\n | {kind:'feature';featureId:string}\n | ({kind:'face'}&SolidFaceReference)\n /** A straight sketch line: the plane through it along the sketch's normal. */\n | {kind:'sketch-line';sourceFeatureId:string;contourId:string;segmentId:string};\n\nexport type FaceTransform=Extract<PartTransform,{kind:'translate'|'translate-reference'|'rotate'|'rotate-reference'}>;\n\nexport type SolidFaceReference=FaceSource & (\n  {normal:[number,number,number];surfaceType?:never} | {surfaceType:CurvedSurfaceType;normal?:never}\n);\n\nexport type SketchPlane = \"XY\" | \"XZ\" | \"YZ\";\n\nexport type PartTransform=NumericPartTransform\n | {kind:'translate-reference';reference:TransformVectorReference;distanceMillimeters?:number;reversed?:boolean}\n | {kind:'rotate-reference';reference:TransformVectorReference;angleDegrees:number}\n | {kind:'scale-reference';centerReference:ExtrusionPointReference;scaleFactors:Vector3}\n | {kind:'mirror';plane:MirrorPlaneReference;/** Join the image with the original instead of making a new part. */combine?:boolean}\n /** Align (SolidCraft's solid.align): move the parts so `from` meets `to`;\n\nexport type CurvedSurfaceType=typeof curvedSurfaceTypes[number];",
  "pattern": "export type PatternFeature = {\n  id: string;\n  type: 'pattern';\n  name: string;\n  suppressed: boolean;\n  sourceFeatureId: string;\n  /** Pattern whole parts instead of the source feature's tool: each copy is a new part `${copyBodyIds[id]}:${i}`. */\n  bodyIds?: string[];\n  copyBodyIds?: Record<string,string>;\n  axis: 'X' | 'Y' | 'Z';\n  count: number;\n  reversed: boolean;\n  /** Where the original sits in the row: first (right, the default), middle, or last. */\n  alignment?: 'left' | 'center' | 'right';\n  targetBodyId?: string;\n} & (\n  | {patternType:'linear';spacingMillimeters:number;\n     /** Replaces `axis` when present. */ direction?: PatternDirection;\n     /** A second row of the whole first row. */ second?: {axis?: 'X' | 'Y' | 'Z'; direction?: PatternDirection; count: number; spacingMillimeters: number; reversed?: boolean; alignment?: 'left' | 'center' | 'right'}}\n  | {patternType:'polar';angleDegrees:number; /** Replaces `axis` (through the origin) when present. */ axisReference?: PatternAxis}\n  | {patternType:'path';pathFeatureId:string;pathContourId?:string;spacingMillimeters?:number;distanceMillimeters?:number;orientation?:'identical'|'path'}\n);\n\nexport type PatternDirection={kind:'vector';direction:[number,number,number]}|SolidEdgeReference;\n\nexport type PatternAxis={kind:'vector';origin:[number,number,number];direction:[number,number,number]}|{kind:'feature';featureId:string}|SolidEdgeReference;\n\nexport interface SolidEdgeReference {\n kind:'solid-edge';sourceFeatureId:string;bodyId:string;anchor:SolidEdgeAnchor;label:string;\n}",
